/*
 * The Sylor star — Sylor's universal mark (a twelve-ray terracotta sunburst). Ported from the
 * marketing site's SylorStar / public/sylor-star.svg so the desktop app shows the exact same
 * logo as the website and /chat. Pure geometry (no asset, no build step), razor-sharp at any
 * size. The terracotta #cf5535 fill is fixed so the mark reads identically on both the warm
 * "paper" and dark themes. Keep it in sync with the site component and with the app icon
 * (app/resources/icon.*, regenerated by scripts/build-star-icon.py from this same geometry).
 */

/** The two rays, alternating around twelve 30° steps about the centre (12,12). */
const LONG_RAY = 'M12 1.4C12.85 6 12.85 8.4 12 11C11.15 8.4 11.15 6 12 1.4Z'
const SHORT_RAY = 'M12 4.8C12.6 7.4 12.6 8.9 12 11C11.4 8.9 11.4 7.4 12 4.8Z'

interface SylorStarProps {
  /** Rendered width/height in px. */
  size?: number
  /** Fill colour. Defaults to Sylor terracotta so the mark looks identical everywhere. */
  color?: string
  className?: string
  title?: string
}

export function SylorStar({
  size = 24,
  color = '#cf5535',
  className = '',
  title = 'Sylor'
}: SylorStarProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill={color}
      role="img"
      aria-label={title}
      className={className}
    >
      <title>{title}</title>
      {Array.from({ length: 12 }).map((_, i) => (
        <path key={i} d={i % 2 === 0 ? LONG_RAY : SHORT_RAY} transform={`rotate(${i * 30} 12 12)`} />
      ))}
    </svg>
  )
}
